// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    Attacker attacker;
    uint256 constant F = 2 ether;

    function setUp() public { c = new X_WALLET(address(new Log())); attacker = new Attacker(c); }

    function testFuzz_property(uint256 am, uint256 nv) public {
        am = bound(am, 2, F);
        nv = bound(nv, 1, am - 1);

        vm.deal(address(this), F);
        attacker.fund{value: F}();          // attacker balance in c = F, unlockTime = now
        vm.warp(block.timestamp + 1);       // unlockTime now in the past

        attacker.attack(am, nv);            // Collect(am); nested Put(nv) from receive()

        // Rule: because the guard blocks the nested Put, the Collect fails as a whole
        // (attacker's receive reverts, low-level call returns false) and the recorded
        // balance is untouched. In the mutant the nested Put succeeds, so the recorded
        // balance becomes F + nv - am != F.
        (, uint256 bal) = c.Acc(address(attacker));
        assertTrue(bal == F, "failed Collect must leave recorded balance unchanged");
    }
}

contract Attacker {
    X_WALLET c;
    uint256 nestedVal;

    constructor(X_WALLET _c) { c = _c; }

    function fund() external payable { c.Put{value: msg.value}(0); }

    function attack(uint256 am, uint256 nv) external {
        nestedVal = nv;
        c.Collect(am);
    }

    receive() external payable {
        c.Put{value: nestedVal}(0); // reverts under the lock in the reference
    }
}
